import * as signalR from '@microsoft/signalr';

export class SignalRService {
  private connection: signalR.HubConnection | null = null;

  async connect(url: string): Promise<void> {
    this.connection = new signalR.HubConnectionBuilder().withUrl(url).withAutomaticReconnect().build();
    await this.connection.start();
  }

  // CAMBIO DE ESTA STORY (SR-3): antes resolvía con éxito aunque TODAS las suscripciones fallaran.
  // Ahora rechaza cuando ninguna suscripción se pudo registrar.
  async subscribeToTopics(topics: string[]): Promise<void> {
    if (!this.connection) throw new Error('not connected');
    const results = await Promise.allSettled(topics.map((t) => this.connection!.invoke('Subscribe', t)));
    const failed = results.filter((r) => r.status === 'rejected').length;
    if (failed === topics.length && topics.length > 0) {
      throw new Error(`subscribeToTopics: ${failed}/${topics.length} suscripciones fallaron`);
    }
  }
}

export const signalRService = new SignalRService();

import { SignalRService } from './signalr.service';
describe('SignalRService.subscribeToTopics', () => {
  it('SubscribeToTopics_TodasFallan_Rechaza', async () => {
    const s: any = new SignalRService();
    s.connection = { invoke: () => Promise.reject(new Error('x')) };
    await expect(s.subscribeToTopics(['a', 'b'])).rejects.toThrow('2/2 suscripciones fallaron');
  });
  it('SubscribeToTopics_UnaEntra_Resuelve', async () => {
    const s: any = new SignalRService();
    let n = 0;
    s.connection = { invoke: () => (n++ === 0 ? Promise.reject(new Error('x')) : Promise.resolve()) };
    await expect(s.subscribeToTopics(['a', 'b'])).resolves.toBeUndefined();
  });
});

